 sampled=rng.choice(groups,size=len(groups),replace=True);ix=np.concatenate([member[g] for g in sampled]);boot_s.append(float(np.mean(special[ix]>=.5)));boot_b.append(float(np.mean(shared[ix]>=.5)))
